import {DraftDecision} from './issue-draft.jsx';
import {discardDraft} from './issue-draft.js';
import {useState,useRef,useEffect,useLayoutEffect} from 'preact/hooks';
import {Notice,Empty,Field,Button,ConfirmButton} from '../../components/ui.jsx';
import {Markdown} from './markdown-view.jsx';
import {MarkdownEditor} from './markdown-editor.jsx';
export {Markdown} from './markdown-view.jsx';
import {RELATION_KINDS,relationCaption} from '../../../../shared/src/schemas/discussion.js';
import {insertMention,canEditComment} from './issue-state.js';
import {WorkPicker,useIssuePages,PageMore} from './issue-controls.jsx';
export function CommentComposer({api,project,initial,onSave,onCancel,label='Post comment',onDirty=()=>{}}) {
  const [baseline,setBaseline]=useState(initial),[body,setBody]=useState(initial?.body??'');
  const [error,setError]=useState(null),[latest,setLatest]=useState(null),[busy,setBusy]=useState(false);
  const pending=useRef(false),active=useRef(true),lost=[401,403,404].includes(error?.status);
  useEffect(()=>()=>{active.current=false;},[]);
  const dirty=body!==(baseline?.body??'');
  useLayoutEffect(()=>{onDirty(dirty);},[dirty]);
  function cancel(){if(discardDraft({body:baseline?.body??''},{body},globalThis.confirm))onCancel();}
  function keep(record,values){setBaseline(record);setBody(values.body);setError(null);setLatest(null);}
  async function inspect(){try{setLatest((await api.get('/comments/'+baseline.id)).comment);}catch(next){setError(next);}}
  function load(record){setBaseline(record);setBody(record.body);setError(null);setLatest(null);}
  async function submit(event) {
    event.preventDefault();if(pending.current||lost)return;pending.current=true;setError(null);setLatest(null);setBusy(true);
    try{await onSave({body,...(baseline?{expectedRevision:baseline.revision}:{})});if(active.current)setBody('');}
    catch(error){if(active.current)setError(error);}finally{pending.current=false;if(active.current)setBusy(false);}
  }
  return <form onSubmit={submit} className="comment-composer">
    <DraftDecision error={error} latest={latest} before={{body:baseline?.body??''}} mine={{body}} current={{body:latest?.body??''}} onInspect={baseline?inspect:null} onLoad={load} onApply={keep} busy={busy}/>
    <fieldset disabled={busy||lost}><legend>{baseline?'Edit comment':'Write a comment'}</legend>
      <MarkdownEditor name="body" label="Comment" value={body} onChange={setBody} error={error?.details?.body} disabled={busy} rows={5} required placeholder="Discuss this issue. Markdown and @mentions are supported." previewLabel="Comment preview"/>
      <WorkPicker api={api} project={project} type="users" permission="comment:write" label="Mention a person" value="" onChange={(id,item)=>{if(item)setBody(previous=>insertMention(previous,{...item,userId:id}));}}/>
      <p className="field-help">Raw HTML is escaped. Mentions notify people who can read this project.</p>
      <div className="actions"><Button busy={busy} disabled={lost||error?.status===409||!body.trim()}>{label}</Button></div>
    </fieldset>
    {onCancel&&<Button type="button" onClick={cancel} disabled={busy}>Cancel comment editing</Button>}
  </form>;
}
export function IssueComments(props) {return <Comments key={props.issue.id} {...props}/>;}
function Comments({issue,project,api,user,canAdmin}) {
  const list=useIssuePages(api,'/issues/'+issue.id+'/comments');
  const [editing,setEditing]=useState(null),[error,setError]=useState(null),[busy,setBusy]=useState(false);
  const pending=useRef(false),dirty=useRef(false);
  async function remove(comment){
    if(pending.current)return;pending.current=true;setBusy(true);setError(null);
    try{await api.delete('/comments/'+comment.id);if(editing?.id===comment.id)setEditing(null);list.reload();}
    catch(error){setError(error);}finally{pending.current=false;setBusy(false);}
  }
  return <section aria-label="Issue comments"><h2>Discussion</h2><Notice error={error}/>
    {list.items.map(comment=><article className="issue-comment" id={'comment-'+comment.id} key={comment.id}>
      <header><strong>{comment.author.name}</strong><time dateTime={comment.createdAt}>{new Date(comment.createdAt).toLocaleString()}</time>{comment.updatedAt!==comment.createdAt&&<span>edited</span>}</header>
      <Markdown source={comment.body}/>
      {canEditComment(comment,user.id,canAdmin,issue.archived)&&<div className="actions"><Button disabled={busy} onClick={()=>{if(editing?.id===comment.id)return;if(!editing||!dirty.current||globalThis.confirm('Discard your unsaved changes?')){dirty.current=false;setEditing(comment);}}}>Edit comment</Button><ConfirmButton disabled={busy} message="Delete this comment?" onConfirm={()=>remove(comment)}>Delete comment</ConfirmButton></div>}
    </article>)}
    {!list.loading&&!list.error&&!list.items.length&&<Empty>No comments yet. Start the discussion below.</Empty>}
    <PageMore list={list} label="comments"/>
    {editing&&<CommentComposer key={editing.id} api={api} project={project} initial={editing} onDirty={value=>{dirty.current=value;}} label="Save comment" onCancel={()=>setEditing(null)} onSave={async body=>{await api.patch('/comments/'+editing.id,body);setEditing(null);list.reload();}}/>}
    {!issue.archived&&<CommentComposer key={'new-'+issue.id} api={api} project={project} onSave={async body=>{await api.post('/issues/'+issue.id+'/comments',body);list.reload();}}/>}
  </section>;
}
export function IssueRelations(props) {return <Relations key={props.issue.id} {...props}/>;}
function Relations({issue,project,api,editable}) {
  const list=useIssuePages(api,'/issues/'+issue.id+'/relations');
  const [target,setTarget]=useState(''),[kind,setKind]=useState('relates');
  const [error,setError]=useState(null),[busy,setBusy]=useState(false),pending=useRef(false);
  async function mutate(action){
    if(pending.current)return;pending.current=true;setBusy(true);setError(null);
    try{await action();list.reload();}catch(error){setError(error);}finally{pending.current=false;setBusy(false);}
  }
  async function add(event){event.preventDefault();await mutate(async()=>{await api.post('/issues/'+issue.id+'/relations',{targetIssueId:target,kind});setTarget('');});}
  return <section aria-label="Issue relations"><h2>Related issues</h2><Notice error={error}/>
    {list.items.length?<ul>{list.items.map(relation=><li key={relation.id}><span>{relation.caption} </span><a href={'#/issues/'+relation.relatedIssue.id}>{relation.relatedIssue.key} · {relation.relatedIssue.title}</a>{editable&&<ConfirmButton disabled={busy} message="Remove this relation?" onConfirm={()=>mutate(()=>api.delete('/relations/'+relation.id))}>Remove relation</ConfirmButton>}</li>)}</ul>:!list.loading&&!list.error&&<Empty>No related issues.</Empty>}
    <PageMore list={list} label="relations"/>
    {editable&&<form className="relation-form" onSubmit={add}><fieldset disabled={busy}><legend>Add related issue</legend>
      <Field label="Relation" error={error?.details?.kind}><select value={kind} onChange={event=>setKind(event.currentTarget.value)}>{RELATION_KINDS.map(value=><option key={value} value={value}>{relationCaption(value,'outgoing')}</option>)}</select></Field>
      <WorkPicker api={api} project={project} type="relations" issueId={issue.id} permission="issue:write" label="Related issue" value={target} onChange={setTarget} required placeholder="Choose an accessible issue"/>
      <Notice error={error?.details?.targetIssueId}/><Button busy={busy} disabled={!target}>Add relation</Button>
    </fieldset></form>}
  </section>;
}

import {DraftDecision} from './issue-draft.jsx';
import {discardDraft} from './issue-draft.js';
import {changedFields} from './issue-state.js';
import {useState,useRef,useEffect} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading,ConfirmButton} from '../../components/ui.jsx';
import {useScopedLoad} from '../insight/scoped-load.js';
import {useIssuePages,PageMore} from './issue-controls.jsx';
export function ProjectLabels(props) {return <Labels key={props.params.projectId} {...props}/>;}
function Labels({params,api}) {
  const projectId=params.projectId;
  const result=useScopedLoad(projectId,()=>api.get('/projects/'+projectId),[projectId]);
  const [q,setQ]=useState(''),[name,setName]=useState(''),[color,setColor]=useState('#5965d8');
  const list=useIssuePages(api,'/projects/'+projectId+'/labels?q='+encodeURIComponent(q));
  const [editing,setEditing]=useState(null),[error,setError]=useState(null),[latest,setLatest]=useState(null),[busy,setBusy]=useState(false);
  const pending=useRef(false),inspection=useRef(0);
  useEffect(()=>()=>{inspection.current++;},[]);
  const accessLost=[401,403,404].includes(error?.status);
  function reset(){inspection.current++;setEditing(null);setName('');setColor('#5965d8');setError(null);setLatest(null);}
  const before=editing?{name:editing.name,color:editing.color}:{name:'',color:'#5965d8'},mine={name,color};
  function cancel(){if(discardDraft(before,mine,globalThis.confirm))reset();}
  function edit(label){inspection.current++;setEditing(label);setName(label.name);setColor(label.color);setError(null);setLatest(null);}
  function choose(label){if(editing?.id===label.id)return;if(discardDraft(before,mine,globalThis.confirm))edit(label);}
  function keep(record,values){inspection.current++;setEditing(record);setName(values.name);setColor(values.color);setError(null);setLatest(null);}
  async function inspect(){
    const ticket=++inspection.current,id=editing.id;
    try{const {label}=await api.get('/labels/'+id);if(ticket===inspection.current)setLatest(label);}
    catch(next){if(ticket===inspection.current)setError(next);}
  }
  async function save(event){
    event.preventDefault();if(pending.current||accessLost)return;inspection.current++;pending.current=true;setBusy(true);setError(null);setLatest(null);
    try{
      if(editing)await api.patch('/labels/'+editing.id,{...changedFields(before,mine),expectedRevision:editing.revision});
      else await api.post('/projects/'+projectId+'/labels',{name,color});
      reset();list.reload();
    }catch(error){setError(error);}finally{pending.current=false;setBusy(false);}
  }
  async function remove(label){if(pending.current)return;pending.current=true;setBusy(true);try{await api.delete('/labels/'+label.id);if(editing?.id===label.id)reset();list.reload();}catch(error){setError(error);}finally{pending.current=false;setBusy(false);}}
  if(result.loading)return <Loading/>;
  if(result.error)return <Notice error={result.error}/>;
  const editable=!result.data.project.archived&&result.data.permissions.write;
  return <Page title={result.data.project.key+' labels'} actions={<a href={'#/projects/'+projectId+'/issues'}>Issues</a>}>
    {result.data.project.archived&&<Notice>This project is archived and read-only.</Notice>}
    <DraftDecision error={error} latest={latest} before={before} mine={mine} current={{name:latest?.name,color:latest?.color}} onInspect={editing?inspect:null} onLoad={edit} onApply={keep} busy={busy}/>
    {editable&&<form onSubmit={save}><fieldset disabled={busy||accessLost}><legend>{editing?'Edit label':'New label'}</legend>
      <Field label="Label name" name="name" value={name} required maxLength={60} error={error?.details?.name} onInput={event=>setName(event.currentTarget.value)}/>
      <Field label="Color" name="color" type="color" value={color} error={error?.details?.color} onInput={event=>setColor(event.currentTarget.value)}/>
      <Button busy={busy} disabled={accessLost||error?.status===409}>{editing?'Save label':'Create label'}</Button>
    </fieldset><Button type="button" disabled={busy} onClick={cancel}>Cancel editing</Button></form>}
    <Field label="Search labels" name="labelSearch" type="search" value={q} onInput={event=>setQ(event.currentTarget.value)}/>
    {list.items.length?<ul>{list.items.map(label=><li key={label.id}><span className="label-chip" style={{borderColor:label.color}}>{label.name}</span>{editable&&<><Button disabled={busy} onClick={()=>choose(label)}>Edit {label.name}</Button><ConfirmButton disabled={busy} message={'Remove '+label.name+' from this project and its issues?'} onConfirm={()=>remove(label)}>Delete {label.name}</ConfirmButton></>}</li>)}</ul>:!list.loading&&!list.error&&<Empty>No labels match.</Empty>}
    <PageMore list={list} label="labels"/>
  </Page>;
}

