    if(mode==='denial'){client=server.agent();const guest=await client('POST','/auth/signup',{name:'Guest editor',email:'draft-guest@example.test',password:'correct-horse-battery'});guestId=guest.data.user.id;cookie=guest.cookie;await api('POST','/orgs/'+org.id+'/members',{userId:guestId,role:'guest'});await api('POST','/projects/'+project.id+'/guests',{userId:guestId});}
    const comment=(await client('POST','/issues/'+issue.id+'/comments',{body:'Before comment'})).data.comment;
    const settings={mode,url:server.url,cookie,adminCookie:mode==='denial'?auth.cookie:undefined,guestId,projectId:project.id,issueId:issue.id,labelId:label.id,otherLabelId:otherLabel.id,commentId:comment.id};
    const result=await new Promise((resolve,reject)=>{child=spawn('/usr/bin/python3',[fileURLToPath(new URL('./issue-draft-browser.py',import.meta.url)),JSON.stringify(settings)],{detached:true});let stdout='',stderr='';const timer=setTimeout(()=>{try{process.kill(-child.pid,'SIGKILL');}catch{}reject(new Error('Draft browser exceeded 55 seconds'));},55000);child.stdout.on('data',value=>stdout+=value);child.stderr.on('data',value=>stderr+=value);child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr});});});
    assert.equal(result.code,0,result.stderr);assert.equal(JSON.parse(result.stdout.trim()).ok,true);
  }finally{if(child?.pid){try{process.kill(-child.pid,'SIGKILL');}catch{}}await server.close();}
}
